// === Tab: mySketch ===
let n = 1;
let m = 720;

let p = 600;

int [][][] x = new Array(n)[m][8];
int [][][] l = new Array(n)[m][8];
int [][][] sw = new Array(n)[m][8];
color [][][] c1 = new Array(n)[m][8];
color [][][] c2 = new Array(n)[m][8];
let rgb1 = new Array(p);
let rgb2 = new Array(p);
let rgb2start = new Array(p);

float [] xp = new Array(n);
float [] yp = new Array(n);

float [] r = new float [n];
float [] cc1 = new Array(n);
float [] cc2 = new Array(n);

function setup(){
  createCanvas(800, 800);
  background(40);


  colorMode(HSB,360,100,100);
  strokeWeight(10);

  stroke(255,255,0);
  for(j=0; j<n; j++){
    xp[j]=random(100,width-100);
    yp[j]=random(height/2,3*height/4);
    r[j]=random(30,90);
    cc1[j]=random(160,240);
    cc2[j]=random(90,120);
   for(i = 0; i<m; i++){
     for(k = 0; k < 8; k++){
       x[j][i][k]=k*120+int(random(-20,20));
       l[j][i][k]=int(random(5,60));
       sw[j][i][k] = int(random(0.25,3.0));
       c1[j][i][k] = color(cc1[j]+random(-40,40),random(80,100),random(80,100));
       c2[j][i][k] = color(cc2[j]+random(-40,40),random(80,100),random(80,100));
     }
   }
  }

  for(i=0; i<p; i++){
    rgb1[i]=int(random(200,250));
  }

  for(i=0; i<p; i++){
    rgb2[i]=int(random(120,180));
	 rgb2start[i]=random(PI);
  }

}



function draw(){
    fill(20,30);
    rect(0,0,width,height);

    pushMatrix();
    translate(xp[0],yp[0]);

    pushMatrix();
    rotate(0.004*frameCount);

    for(i=0; i<p; i++){
      //if(i<p/2)
       fill(int(rgb1[i]-80*sin(0.01*frameCount))%360,40,80);
    //else
    //   fill(int(rgb[i]-40+80*noise(0.01*frameCount))%360,40,60); //fill(rgb[i],40,60);
      arc(0,0,width*2.5,width*2.5,0,TWO_PI/p);
      rotate(TWO_PI/p);
    }

    popMatrix();

    for(i=0; i<p/2; i++){

      fill(rgb2[i],75,50*abs(sin(rgb2start[i]+0.04*frameCount))); //fill(rgb[i],40,60);
      arc(0,0,width*2.5,width*2.5,0,TWO_PI/p);
      rotate(TWO_PI/p);
    }

    popMatrix();



  stroke(0);
    for(i=0; i<n; i++){
      pushMatrix();
      translate(xp[i],yp[i]);
      //ellipse(0,0,100,100);

      for(alpha=0; alpha<m; alpha+=2){
        rotate(radians(2*360/m));
        for(k =0; k < 8; k++){
          x[i][alpha][k]+=3;
          if ((x[i][alpha][k])+(l[i][alpha][k]) > 900){
            x[i][alpha][k] = 0;
          }
          strokeWeight(sw[i][alpha][k]);
          if(alpha<m/2)
           stroke(c1[i][alpha][k]); //,100-10*k);
           else
           stroke(c2[i][alpha][k]);
          line(x[i][alpha][k],0,x[i][alpha][k]+l[i][alpha][k],0);
        }
      }

      popMatrix();
    }


     noStroke();

    for(i=0; i<n; i++){
      pushMatrix();
      translate(xp[i],yp[i]);

		for(k=0; k<6; k++){
      fill(int(cc1[i]+180*sin(0.01*frameCount))%360,k*2+60*sq(sin(PI/800*frameCount)),k*2+60*sq(sin(PI/800*frameCount)));
      arc(0,0,1.25*r[i]*(6-k)/6,1.25*r[i]*(6-k)/6,PI,TWO_PI);
		}
      popMatrix();
    }




}

